import os,re
root='/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge'
def mod2path(m):
    return os.path.join(root, m.replace('.','/')+'.lean')
seen=set()
stack=['AlgebraicJacobian']
while stack:
    m=stack.pop()
    if m in seen: continue
    seen.add(m)
    p=mod2path(m)
    if not os.path.exists(p): continue
    for line in open(p, errors='replace'):
        mm=re.match(r'import\s+(AlgebraicJacobian[\w.]*)', line)
        if mm: stack.append(mm.group(1))
print('closure size:', len(seen))
for m in sorted(seen):
    if 'SymPow' in m or 'Albanese' in m and 'Invariants' in m: print('  in closure:', m)
for f in ['SymPowTensorAction','SymPowInvariantsUnder','SymPowInvariants','SymPowInvariantsLocalization','SymPowInterface','SymPowColimit']:
    print(f, 'AlgebraicJacobian.Albanese.'+f in seen)
EOF

